                return Err(hir_error(
                    "char literal bits are not a Unicode scalar value",
                ));
            }
            self.finish_expr(
                expression,
                &ResolvedType::Char,
                OwnershipMode::Value,
            )?;
            scopes.push(scope)?;
        }
        ResolvedExprKind::Uint8(_) => {
            self.finish_expr(expression, &ResolvedType::U8, OwnershipMode::Value)?;
            scopes.push(scope)?;
        }
        ResolvedExprKind::Usize(_) => {
            self.finish_expr(
                expression,
                &ResolvedType::Usize,
                OwnershipMode::Value,
            )?;
            scopes.push(scope)?;
        }
