                hir_error("fixed-array literal length does not fit u32")
            })?;
            self.finish_expr(
                expression,
                &ResolvedType::ArrayU8(length),
                OwnershipMode::Value,
            )?;
            scopes.push(scope)?;
        }
        ResolvedExprKind::RepeatArrayU8 { count, .. } => {
