            callee,
            type_arguments,
            instance,
            args,
        } => {
            let owned_generic_intrinsic = box_intrinsic::is_call(callee, instance);
            match instance {
                None if !type_arguments.is_empty() && !owned_generic_intrinsic => {
                    return Err(hir_error(
                        "monomorphic resolved call carries generic type arguments",
                    ));
                }
