            frames.push(Frame::IfCondition {
                expression,
                then_branch,
                else_branch,
                path,
            })?;
            frames.push(Frame::Enter {
                expression: condition,
                scope,
                path: path_label::Label::child(path, ".condition", [0, 0])?,
